1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { parseMarkdownFile } from './frontmatter';
4	import { renderMarkdown } from './markdown';
5	import { Page } from './page';
6	import { DEFAULT_LAYOUT_NAME, DEFAULT_TEMPLATE_NAME, INDEX_TEMPLATE_NAME, TemplateEngine } from './templates';
7	
8	export interface BuildOptions {
9	  contentDir: string;
10	  outputDir: string;
11	  templatesDir?: string;
12	}
13	
14	export interface BuildResult {
15	  pages: Page[];
16	  outputDir: string;
17	}
18	
19	function findMarkdownFiles(dir: string): string[] {
20	  if (!fs.existsSync(dir)) {
21	    throw new Error(`Content directory not found: ${dir}`);
22	  }
23	
24	  const results: string[] = [];
25	  const entries = fs.readdirSync(dir, { withFileTypes: true });
26	
27	  for (const entry of entries) {
28	    const fullPath = path.join(dir, entry.name);
29	    if (entry.isDirectory()) {
30	      results.push(...findMarkdownFiles(fullPath));
31	    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
32	      results.push(fullPath);
33	    }
34	  }
35	
36	  return results.sort();
37	}
38	
39	function slugFromPath(contentDir: string, filePath: string): string {
40	  const relative = path.relative(contentDir, filePath);
41	  const withoutExt = relative.replace(/\.md$/i, '');
42	  return withoutExt.split(path.sep).join('/');
43	}
44	
45	function titleFromSlug(slug: string): string {
46	  const base = slug.split('/').pop() || slug;
47	  return base
48	    .replace(/[-_]+/g, ' ')
49	    .replace(/\b\w/g, (char) => char.toUpperCase());
50	}
51	
52	export function buildPage(contentDir: string, filePath: string): Page {
53	  const raw = fs.readFileSync(filePath, 'utf-8');
54	  const { data, content } = parseMarkdownFile(raw);
55	  const slug = slugFromPath(contentDir, filePath);
56	  const html = renderMarkdown(content);
57	
58	  const title = typeof data.title === 'string' && data.title.trim() ? data.title : titleFromSlug(slug);
59	  const date = typeof data.date === 'string' && data.date.trim() ? data.date : null;
60	  const tags = Array.isArray(data.tags) ? data.tags.map(String) : [];
61	  const template = typeof data.template === 'string' && data.template.trim() ? data.template : DEFAULT_TEMPLATE_NAME;
62	  const layout = typeof data.layout === 'string' && data.layout.trim() ? data.layout : DEFAULT_LAYOUT_NAME;
63	
64	  return {
65	    slug,
66	    title,
67	    date,
68	    tags,
69	    html,
70	    sourcePath: filePath,
71	    outputPath: `${slug}.html`,
72	    template,
73	    layout,
74	  };
75	}
76	
77	export function buildSite(options: BuildOptions): BuildResult {
78	  const contentDir = path.resolve(options.contentDir);
79	  const outputDir = path.resolve(options.outputDir);
80	  const templatesDir = path.resolve(options.templatesDir ?? './templates');
81	
82	  const files = findMarkdownFiles(contentDir);
83	  const pages = files.map((file) => buildPage(contentDir, file));
84	
85	  const templateEngine = new TemplateEngine(templatesDir);
86	
87	  fs.mkdirSync(outputDir, { recursive: true });
88	
89	  for (const page of pages) {
90	    const destPath = path.join(outputDir, page.outputPath);
91	    fs.mkdirSync(path.dirname(destPath), { recursive: true });
92	    const html = templateEngine.render(page.template, page.layout, { ...page });
93	    fs.writeFileSync(destPath, html, 'utf-8');
94	  }
95	
96	  const indexPath = path.join(outputDir, 'index.html');
97	  const indexHtml = templateEngine.render(INDEX_TEMPLATE_NAME, DEFAULT_LAYOUT_NAME, { title: 'Index', pages });
98	  fs.writeFileSync(indexPath, indexHtml, 'utf-8');
99	
100	  return { pages, outputDir };
101	}
