1	#!/usr/bin/env node
2	import { Command } from 'commander';
3	import { buildSite } from './site';
4	import { startDevServer } from './serve';
5	
6	export function run(argv: string[]): void {
7	  const program = new Command();
8	
9	  program.name('ssg').description('A static site generator CLI');
10	
11	  program
12	    .command('build')
13	    .description('Generate the site from Markdown content')
14	    .option('--content <dir>', 'content directory', './content')
15	    .option('--output <dir>', 'output directory', './dist')
16	    .option('--templates <dir>', 'templates directory', './templates')
17	    .action((opts: { content: string; output: string; templates: string }) => {
18	      const result = buildSite({ contentDir: opts.content, outputDir: opts.output, templatesDir: opts.templates });
19	      // eslint-disable-next-line no-console
20	      console.log(`Built ${result.pages.length} page(s) into ${result.outputDir}`);
21	    });
22	
23	  program
24	    .command('serve')
25	    .description('Build the site and start a live-reload development server')
26	    .option('--content <dir>', 'content directory', './content')
27	    .option('--output <dir>', 'output directory', './dist')
28	    .option('--templates <dir>', 'templates directory', './templates')
29	    .option('--port <port>', 'port to serve on', '3000')
30	    .action(async (opts: { content: string; output: string; templates: string; port: string }) => {
31	      const port = Number.parseInt(opts.port, 10);
32	      const server = await startDevServer({
33	        contentDir: opts.content,
34	        outputDir: opts.output,
35	        templatesDir: opts.templates,
36	        port,
37	      });
38	      // eslint-disable-next-line no-console
39	      console.log(`Dev server running at ${server.url}`);
40	      // eslint-disable-next-line no-console
41	      console.log(`Watching ${opts.content} and ${opts.templates} for changes...`);
42	    });
43	
44	  program.parse(argv);
45	}
46	
47	if (require.main === module) {
48	  run(process.argv);
49	}
