1	import * as fs from 'fs';
2	import * as http from 'http';
3	import * as path from 'path';
4	import chokidar from 'chokidar';
5	import { WebSocket, WebSocketServer } from 'ws';
6	import { buildSite, BuildOptions } from './site';
7	
8	export interface ServeOptions extends BuildOptions {
9	  port?: number;
10	}
11	
12	export interface DevServer {
13	  url: string;
14	  port: number;
15	  close: () => Promise<void>;
16	}
17	
18	export const LIVERELOAD_PATH = '/__livereload';
19	
20	const REBUILD_DEBOUNCE_MS = 50;
21	
22	const MIME_TYPES: Record<string, string> = {
23	  '.html': 'text/html; charset=utf-8',
24	  '.css': 'text/css; charset=utf-8',
25	  '.js': 'text/javascript; charset=utf-8',
26	  '.json': 'application/json; charset=utf-8',
27	  '.svg': 'image/svg+xml',
28	  '.png': 'image/png',
29	  '.jpg': 'image/jpeg',
30	  '.jpeg': 'image/jpeg',
31	  '.gif': 'image/gif',
32	  '.ico': 'image/x-icon',
33	  '.txt': 'text/plain; charset=utf-8',
34	};
35	
36	function liveReloadScript(): string {
37	  return `
38	<script>
39	(function () {
40	  var socket = new WebSocket('ws://' + window.location.host + '${LIVERELOAD_PATH}');
41	  socket.addEventListener('message', function (event) {
42	    if (event.data === 'reload') {
43	      window.location.reload();
44	    }
45	  });
46	})();
47	</script>
48	`;
49	}
50	
51	export function injectLiveReload(html: string): string {
52	  const script = liveReloadScript();
53	  if (html.includes('</body>')) {
54	    return html.replace('</body>', `${script}</body>`);
55	  }
56	  return `${html}${script}`;
57	}
58	
59	function resolveFilePath(outputDir: string, urlPath: string): string {
60	  const decoded = decodeURIComponent(urlPath.split('?')[0] ?? '/');
61	  const relative = decoded.replace(/^\/+/, '') || 'index.html';
62	
63	  let filePath = path.join(outputDir, relative);
64	
65	  if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
66	    filePath = path.join(filePath, 'index.html');
67	  } else if (!fs.existsSync(filePath) && !path.extname(filePath)) {
68	    filePath = `${filePath}.html`;
69	  }
70	
71	  return filePath;
72	}
73	
74	function serveFile(outputDir: string, req: http.IncomingMessage, res: http.ServerResponse): void {
75	  const resolvedRoot = path.resolve(outputDir);
76	  const filePath = resolveFilePath(resolvedRoot, req.url ?? '/');
77	  const resolved = path.resolve(filePath);
78	
79	  const isWithinRoot = resolved === resolvedRoot || resolved.startsWith(resolvedRoot + path.sep);
80	  if (!isWithinRoot || !fs.existsSync(resolved) || fs.statSync(resolved).isDirectory()) {
81	    res.statusCode = 404;
82	    res.end('Not found');
83	    return;
84	  }
85	
86	  const ext = path.extname(resolved).toLowerCase();
87	  const contentType = MIME_TYPES[ext] ?? 'application/octet-stream';
88	
89	  if (ext === '.html') {
90	    const html = fs.readFileSync(resolved, 'utf-8');
91	    res.setHeader('Content-Type', contentType);
92	    res.end(injectLiveReload(html));
93	    return;
94	  }
95	
96	  res.setHeader('Content-Type', contentType);
97	  fs.createReadStream(resolved).pipe(res);
98	}
99	
100	export function startDevServer(options: ServeOptions): Promise<DevServer> {
101	  const contentDir = path.resolve(options.contentDir);
102	  const outputDir = path.resolve(options.outputDir);
103	  const templatesDir = path.resolve(options.templatesDir ?? './templates');
104	  const requestedPort = options.port ?? 3000;
105	
106	  const rebuild = (): void => {
107	    buildSite({ contentDir, outputDir, templatesDir });
108	  };
109	
110	  rebuild();
111	
112	  const httpServer = http.createServer((req, res) => serveFile(outputDir, req, res));
113	  const wss = new WebSocketServer({ server: httpServer, path: LIVERELOAD_PATH });
114	
115	  const broadcastReload = (): void => {
116	    wss.clients.forEach((client) => {
117	      if (client.readyState === WebSocket.OPEN) {
118	        client.send('reload');
119	      }
120	    });
121	  };
122	
123	  let rebuildTimer: ReturnType<typeof setTimeout> | null = null;
124	  const scheduleRebuild = (): void => {
125	    if (rebuildTimer) clearTimeout(rebuildTimer);
126	    rebuildTimer = setTimeout(() => {
127	      rebuildTimer = null;
128	      try {
129	        rebuild();
130	        broadcastReload();
131	      } catch (err) {
132	        // eslint-disable-next-line no-console
133	        console.error('Rebuild failed:', err instanceof Error ? err.message : err);
134	      }
135	    }, REBUILD_DEBOUNCE_MS);
136	  };
137	
138	  const watcher = chokidar.watch([contentDir, templatesDir], { ignoreInitial: true });
139	  watcher.on('all', scheduleRebuild);
140	
141	  const watcherReady = new Promise<void>((resolveReady) => watcher.once('ready', () => resolveReady()));
142	
143	  const listening = new Promise<number>((resolve, reject) => {
144	    httpServer.once('error', reject);
145	    httpServer.listen(requestedPort, () => {
146	      const address = httpServer.address();
147	      const actualPort = typeof address === 'object' && address ? address.port : requestedPort;
148	      resolve(actualPort);
149	    });
150	  });
151	
152	  return Promise.all([listening, watcherReady]).then(([actualPort]) => ({
153	    url: `http://localhost:${actualPort}`,
154	    port: actualPort,
155	    close: () =>
156	      new Promise<void>((resolveClose) => {
157	        if (rebuildTimer) clearTimeout(rebuildTimer);
158	        watcher.close().then(() => {
159	          wss.close(() => {
160	            httpServer.close(() => resolveClose());
161	          });
162	        });
163	      }),
164	  }));
165	}
