function titleFromSlug(slug: string): string {
  const base = slug.split('/').pop() || slug;
  return base
    .replace(/[-_]+/g, ' ')
    .replace(/\b\w/g, (char) => char.toUpperCase());
}

/**
 * Built-in plugin that turns a raw `.md` file into a fully populated Page:
 * splits frontmatter from body, renders the body to HTML, and resolves
 * title/date/tags/template/layout (falling back to sensible defaults).
 */
export function markdownPlugin(): Plugin {
  return {
    name: 'markdown',
    onFile(page: Page): Page {
      const raw = fs.readFileSync(page.sourcePath, 'utf-8');
      const { data, content } = parseMarkdownFile(raw);
      const html = renderMarkdown(content);

      const title = typeof data.title === 'string' && data.title.trim() ? data.title : titleFromSlug(page.slug);
      const date = typeof data.date === 'string' && data.date.trim() ? data.date : null;
      const tags = Array.isArray(data.tags) ? data.tags.map(String) : [];
      const template =
        typeof data.template === 'string' && data.template.trim() ? data.template : DEFAULT_TEMPLATE_NAME;
      const layout = typeof data.layout === 'string' && data.layout.trim() ? data.layout : DEFAULT_LAYOUT_NAME;

      return { ...page, title, date, tags, html, template, layout };
    },
  };
}

import * as fs from 'fs';
import * as path from 'path';
import { Page } from '../src/page';
import { Plugin, PluginContext } from '../src/plugin';
import { DEFAULT_LAYOUT_NAME, INDEX_TEMPLATE_NAME, TemplateEngine } from '../src/templates';

/**
 * Built-in plugin that renders each Page through the Handlebars template
 * engine and writes it to disk, then renders and writes the site index once
 * all pages are built.
 */
export function templatePlugin(): Plugin {
  let engine: TemplateEngine;

  return {
    name: 'template',
    beforeBuild(ctx: PluginContext): void {
      engine = new TemplateEngine(ctx.templatesDir);
      fs.mkdirSync(ctx.outputDir, { recursive: true });
    },
    onFile(page: Page, ctx: PluginContext): void {
      const destPath = path.join(ctx.outputDir, page.outputPath);
      fs.mkdirSync(path.dirname(destPath), { recursive: true });
      const html = engine.render(page.template, page.layout, { ...page });
      fs.writeFileSync(destPath, html, 'utf-8');
    },
    afterBuild(pages: Page[], ctx: PluginContext): void {
      const indexPath = path.join(ctx.outputDir, 'index.html');
      const indexHtml = engine.render(INDEX_TEMPLATE_NAME, DEFAULT_LAYOUT_NAME, { title: 'Index', pages });
      fs.writeFileSync(indexPath, indexHtml, 'utf-8');
    },
  };
}

import * as fs from 'fs';
import * as http from 'http';
import * as path from 'path';
import { WebSocket, WebSocketServer } from 'ws';
import { Page } from '../src/page';
import { Plugin } from '../src/plugin';

export const LIVERELOAD_PATH = '/__livereload';

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
};

function liveReloadScript(): string {
  return `
<script>
(function () {
  var socket = new WebSocket('ws://' + window.location.host + '${LIVERELOAD_PATH}');
  socket.addEventListener('message', function (event) {
    if (event.data === 'reload') {
      window.location.reload();
    }
  });
})();
</script>
`;
}

export function injectLiveReload(html: string): string {
  const script = liveReloadScript();
  if (html.includes('</body>')) {
    return html.replace('</body>', `${script}</body>`);
  }
  return `${html}${script}`;
}

function resolveFilePath(outputDir: string, urlPath: string): string {
  const decoded = decodeURIComponent(urlPath.split('?')[0] ?? '/');
  const relative = decoded.replace(/^\/+/, '') || 'index.html';

  let filePath = path.join(outputDir, relative);

  if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
    filePath = path.join(filePath, 'index.html');
  } else if (!fs.existsSync(filePath) && !path.extname(filePath)) {
    filePath = `${filePath}.html`;
  }

  return filePath;
}

function serveFile(outputDir: string, req: http.IncomingMessage, res: http.ServerResponse): void {
  const resolvedRoot = path.resolve(outputDir);
  const filePath = resolveFilePath(resolvedRoot, req.url ?? '/');
  const resolved = path.resolve(filePath);

  const isWithinRoot = resolved === resolvedRoot || resolved.startsWith(resolvedRoot + path.sep);
  if (!isWithinRoot || !fs.existsSync(resolved) || fs.statSync(resolved).isDirectory()) {
    res.statusCode = 404;
    res.end('Not found');
    return;
  }

  const ext = path.extname(resolved).toLowerCase();
  const contentType = MIME_TYPES[ext] ?? 'application/octet-stream';

  if (ext === '.html') {
    const html = fs.readFileSync(resolved, 'utf-8');
    res.setHeader('Content-Type', contentType);
    res.end(injectLiveReload(html));
    return;
  }

  res.setHeader('Content-Type', contentType);
  fs.createReadStream(resolved).pipe(res);
}

/**
 * Built-in plugin that serves the built output over HTTP with a live-reload
 * script injected into every HTML response, and broadcasts a reload message
 * to connected clients at the end of every build it takes part in. Starting
 * and stopping the HTTP/WebSocket server are explicit calls (`listen`,
 * `close`) rather than lifecycle hooks, since they bracket the whole dev
 * session rather than a single build pass.
 */
export class DevServerPlugin implements Plugin {
  readonly name = 'dev-server';

  private readonly outputDir: string;

  private httpServer: http.Server | null = null;

  private wss: WebSocketServer | null = null;

  constructor(outputDir: string) {
    this.outputDir = outputDir;
  }

  afterBuild(_pages: Page[]): void {
    if (!this.wss) return;
    this.wss.clients.forEach((client) => {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    });
  }

  listen(port: number): Promise<{ url: string; port: number }> {
    this.httpServer = http.createServer((req, res) => serveFile(this.outputDir, req, res));
    this.wss = new WebSocketServer({ server: this.httpServer, path: LIVERELOAD_PATH });

    return new Promise((resolve, reject) => {
      const server = this.httpServer as http.Server;
      server.once('error', reject);
      server.listen(port, () => {
        const address = server.address();
        const actualPort = typeof address === 'object' && address ? address.port : port;
        resolve({ url: `http://localhost:${actualPort}`, port: actualPort });
      });
    });
  }

  close(): Promise<void> {
    return new Promise((resolveClose) => {
      const wss = this.wss;
      const httpServer = this.httpServer;
      this.wss = null;
      this.httpServer = null;

      if (!wss || !httpServer) {
        resolveClose();
        return;
      }

      wss.close(() => {
        httpServer.close(() => resolveClose());
      });
    });
  }
}

import * as path from 'path';
import { Plugin } from './plugin';
import { markdownPlugin } from '../plugins/markdown-plugin';
import { templatePlugin } from '../plugins/template-plugin';

export interface SSGConfig {
  plugins: Plugin[];
}

function builtInDefaultPlugins(): Plugin[] {
  return [markdownPlugin(), templatePlugin()];
}

function defaultConfigPath(): string {
  return path.resolve(__dirname, '..', 'ssg.config');
}

/**
 * Loads the plugin pipeline from `ssg.config.ts` (or a custom path). Falls
 * back to the built-in markdown + template plugins whenever no config file
 * is present, or the file exists but doesn't export a usable plugin list -
 * this keeps `buildSite`/`startDevServer` working with zero configuration.
 */
export function loadConfig(configPath?: string): SSGConfig {
  const resolvedPath = configPath ? path.resolve(configPath) : defaultConfigPath();

  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const mod = require(resolvedPath);
    const config = (mod?.default ?? mod) as Partial<SSGConfig> | undefined;
    if (config && Array.isArray(config.plugins) && config.plugins.length > 0) {
      return { plugins: config.plugins };
    }
  } catch {
    // No config file at this path, or it failed to load - use the built-ins.
  }

  return { plugins: builtInDefaultPlugins() };
}

