import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { PluginContext } from '../src/plugin';
import { markdownPlugin } from './markdown-plugin';

function makeTmpDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

function makeCtx(contentDir: string): PluginContext {
  return { contentDir, outputDir: contentDir, templatesDir: contentDir, config: {} };
}

describe('markdownPlugin', () => {
  let contentDir: string;

  beforeEach(() => {
    contentDir = makeTmpDir('ssg-md-plugin-');
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
  });

  it('parses frontmatter and renders markdown into the page', () => {
    const filePath = path.join(contentDir, 'hello.md');
    fs.writeFileSync(filePath, '---\ntitle: Hello\ndate: 2026-01-01\ntags: [a, b]\n---\n\n# Hi there\n');

    const stub = {
      slug: 'hello',
      title: '',
      date: null,
      tags: [],
      html: '',
      sourcePath: filePath,
      outputPath: 'hello.html',
      template: '',
      layout: '',
    };

    const result = markdownPlugin().onFile!(stub, makeCtx(contentDir));

    expect(result).toMatchObject({
      title: 'Hello',
      date: '2026-01-01',
      tags: ['a', 'b'],
    });
    expect(result?.html).toContain('<h1>Hi there</h1>');
  });

  it('falls back to a title derived from the slug when frontmatter has no title', () => {
    const filePath = path.join(contentDir, 'my-cool-post.md');
    fs.writeFileSync(filePath, 'No frontmatter here.');

    const stub = {
      slug: 'my-cool-post',
      title: '',
      date: null,
      tags: [],
      html: '',
      sourcePath: filePath,
      outputPath: 'my-cool-post.html',
      template: '',
      layout: '',
    };

    const result = markdownPlugin().onFile!(stub, makeCtx(contentDir));

    expect(result?.title).toBe('My Cool Post');
    expect(result?.template).toBe('page');
    expect(result?.layout).toBe('default');
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { Page } from '../src/page';
import { PluginContext } from '../src/plugin';
import { templatePlugin } from './template-plugin';

function makeTmpDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

describe('templatePlugin', () => {
  let outputDir: string;
  let templatesDir: string;
  let ctx: PluginContext;

  beforeEach(() => {
    outputDir = makeTmpDir('ssg-tpl-plugin-output-');
    templatesDir = makeTmpDir('ssg-tpl-plugin-templates-');
    fs.mkdirSync(path.join(templatesDir, 'layouts'));
    ctx = { contentDir: outputDir, outputDir, templatesDir, config: {} };
  });

  afterEach(() => {
    fs.rmSync(outputDir, { recursive: true, force: true });
    fs.rmSync(templatesDir, { recursive: true, force: true });
  });

  it('renders each page through its template/layout and writes it to disk', () => {
    fs.writeFileSync(path.join(templatesDir, 'page.hbs'), '<h1>{{title}}</h1>{{{html}}}');
    fs.writeFileSync(path.join(templatesDir, 'layouts', 'default.hbs'), '<body>{{{body}}}</body>');

    const page: Page = {
      slug: 'hello',
      title: 'Hello',
      date: null,
      tags: [],
      html: '<p>Hi</p>',
      sourcePath: '/dev/null',
      outputPath: 'hello.html',
      template: 'page',
      layout: 'default',
    };

    const plugin = templatePlugin();
    plugin.beforeBuild!(ctx);
    plugin.onFile!(page, ctx);

    const written = fs.readFileSync(path.join(outputDir, 'hello.html'), 'utf-8');
    expect(written).toBe('<body><h1>Hello</h1><p>Hi</p></body>');
  });

  it('writes an index.html listing all pages in afterBuild', () => {
    fs.writeFileSync(path.join(templatesDir, 'index.hbs'), 'INDEX:{{#each pages}}{{title}};{{/each}}');
    fs.writeFileSync(path.join(templatesDir, 'layouts', 'default.hbs'), '{{{body}}}');

    const pages: Page[] = [
      {
        slug: 'a',
        title: 'A',
        date: null,
        tags: [],
        html: '',
        sourcePath: '/dev/null',
        outputPath: 'a.html',
        template: 'page',
        layout: 'default',
      },
    ];

    const plugin = templatePlugin();
    plugin.beforeBuild!(ctx);
    plugin.afterBuild!(pages, ctx);

    const written = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf-8');
    expect(written).toBe('INDEX:A;');
  });

  it('creates the output directory in beforeBuild', () => {
    fs.rmSync(outputDir, { recursive: true, force: true });
    expect(fs.existsSync(outputDir)).toBe(false);

    templatePlugin().beforeBuild!(ctx);

    expect(fs.existsSync(outputDir)).toBe(true);
  });
});

import * as fs from 'fs';
import * as http from 'http';
import * as os from 'os';
import * as path from 'path';
import WebSocket from 'ws';
import { DevServerPlugin, injectLiveReload } from './dev-server-plugin';

function makeTmpDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

function get(url: string): Promise<{ statusCode: number; body: string }> {
  return new Promise((resolve, reject) => {
    http
      .get(url, (res) => {
        let body = '';
        res.on('data', (chunk) => {
          body += chunk;
        });
        res.on('end', () => resolve({ statusCode: res.statusCode ?? 0, body }));
      })
      .on('error', reject);
  });
}

describe('DevServerPlugin', () => {
  let outputDir: string;
  let plugin: DevServerPlugin;

  beforeEach(() => {
    outputDir = makeTmpDir('ssg-devplugin-output-');
    fs.writeFileSync(path.join(outputDir, 'index.html'), '<html><body>Hi</body></html>');
    plugin = new DevServerPlugin(outputDir);
  });

  afterEach(async () => {
    await plugin.close();
    fs.rmSync(outputDir, { recursive: true, force: true });
  });

  it('is a no-op broadcast before listen() has been called', () => {
    expect(() => plugin.afterBuild([])).not.toThrow();
  });

  it('serves built files with live reload injected once listening', async () => {
    const { url } = await plugin.listen(0);

    const res = await get(url);
    expect(res.statusCode).toBe(200);
    expect(res.body).toContain('__livereload');
  });

  it('broadcasts "reload" to connected clients on afterBuild', async () => {
    const { port } = await plugin.listen(0);

    const ws = new WebSocket(`ws://localhost:${port}/__livereload`);
    await new Promise<void>((resolve, reject) => {
      ws.once('open', () => resolve());
      ws.once('error', reject);
    });

    const message = new Promise<string>((resolve) => {
      ws.once('message', (data) => resolve(data.toString()));
    });

    plugin.afterBuild([]);

    expect(await message).toBe('reload');
    ws.close();
  });
});

describe('injectLiveReload', () => {
  it('injects the reload script before </body>', () => {
    const result = injectLiveReload('<html><body>Hi</body></html>');
    expect(result).toContain('__livereload');
    expect(result.indexOf('<script>')).toBeLessThan(result.indexOf('</body>'));
  });
});

